<script setup lang="ts">definePageMeta({middleware:'auth'});useHead({title:'علاقه‌مندی‌ها'});const{api}=useShopApi();const{data,refresh}=await useAsyncData('favorites',()=>api<any>('/favorites'));async function remove(id:number){await api(`/favorites/${id}`,{method:'POST'});await refresh()}</script>
<template><div class="mx-auto max-w-7xl px-4 py-10"><div class="flex justify-between"><h1 class="text-2xl font-black">محصولات موردعلاقه</h1><NuxtLink to="/profile" class="text-sm font-bold text-brand-700">بازگشت</NuxtLink></div><div v-if="data?.data?.length" class="mt-7 grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-5"><div v-for="p in data.data" :key="p.id" class="relative"><ProductCard :product="p"/><button class="absolute left-3 top-3 z-10 grid size-9 place-items-center rounded-full bg-white text-rose-600 shadow" @click="remove(p.id)">♥</button></div></div><div v-else class="mt-7 rounded-2xl border border-dashed bg-white p-14 text-center text-slate-400">هنوز محصولی را ذخیره نکرده‌اید.</div></div></template>
